import torch
import torch.nn as nn
from ptx_harness import ptx_load, ptx_launch

PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry argmax_kernel(
    .param .u64 x_ptr,
    .param .u64 out_ptr,
    .param .u32 B,
    .param .u32 D1,
    .param .u32 D2
)
{
    // Load parameters
    .reg .u64 %x, %out;
    .reg .u32 %B, %D1, %D2;
    ld.param.u64 %x, [x_ptr];
    ld.param.u64 %out, [out_ptr];
    ld.param.u32 %B, [B];
    ld.param.u32 %D1, [D1];
    ld.param.u32 %D2, [D2];

    // Thread identifiers
    .reg .u32 %tid, %bid, %ntid, %idx;
    mov.u32 %tid, %tid.x;
    mov.u32 %bid, %ctaid.x;
    mov.u32 %ntid, %ntid.x;
    mad.lo.u32 %idx, %bid, %ntid, %tid;        // idx = blockIdx.x * blockDim.x + threadIdx.x

    // total = B * D2
    .reg .u64 %total;
    mul.wide.u32 %total, %B, %D2;
    setp.ge.u64 %p_exit, %idx, %total;
    @%p_exit bra DONE;

    // Compute (batch, d2) coordinates
    .reg .u32 %batch, %d2, %tmp;
    div.u32 %batch, %idx, %D2;
    mul.lo.u32 %tmp, %batch, %D2;
    sub.u32 %d2, %idx, %tmp;

    // Initialize max value and index
    .reg .f32 %max_val;
    .reg .s32 %max_idx;
    mov.f32 %max_val, -65504.0;   // smallest fp16 value as f32
    mov.s32 %max_idx, -1;

    // Loop over dimension D1
    .reg .u32 %i;
    mov.u32 %i, 0;
LOOP:
    setp.ge.u32 %p_done, %i, %D1;
    @%p_done bra ENDLOOP;

    // offset = ((batch * D1 + i) * D2 + d2)
    .reg .u64 %offset;
    mul.wide.u32 %offset, %batch, %D1;   // batch * D1
    add.u32 %offset, %offset, %i;       // + i
    mul.wide.u32 %offset, %offset, %D2; // * D2
    add.u64 %offset, %offset, %d2;      // + d2

    // Load fp16 element
    .reg .u16 %val_half;
    ld.global.u16 %val_half, [%x + %offset*2];
    // Convert to f32 for comparison
    .reg .f32 %val_f32;
    cvt.f32.f16 %val_f32, %val_half;

    // Compare and possibly update max
    setp.gt.f32 %p_gt, %val_f32, %max_val;
    @%p_gt {
        mov.f32 %max_val, %val_f32;
        mov.s32 %max_idx, %i;
    }

    // i++
    add.u32 %i, %i, 1;
    bra LOOP;
ENDLOOP:

    // Store result (int64) at output[batch, d2]
    .reg .u64 %out_offset, %out_addr, %max_idx_u64;
    mul.wide.u32 %out_offset, %batch, %D2;
    add.u64 %out_offset, %out_offset, %d2;
    mul.wide.u32 %out_addr, %out_offset, 8;   // int64 = 8 bytes
    cvt.u64.s32 %max_idx_u64, %max_idx;
    st.global.u64 [%out + %out_addr], %max_idx_u64;

DONE:
    ret;
}
'''

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        B, D1, D2 = x.shape
        if self.dim == 1:
            out_shape = (B, D2)
        elif self.dim == 2:
            out_shape = (B, D1)
        else:
            raise ValueError("Unsupported dim for argmax")
        out = torch.empty(out_shape, dtype=torch.int64, device=x.device)

        # Launch configuration
        total_elements = B * (D2 if self.dim == 1 else D1)
        threads_per_block = 256
        blocks = (total_elements + threads_per_block - 1) // threads_per_block
        grid = (blocks, 1, 1)
        block = (threads_per_block, 1, 1)

        args = [
            x.data_ptr(),
            out.data_ptr(),
            B,
            D1,
            D2
        ]
        ptx_launch(self.module, "argmax_kernel", grid, block, args)
        return out
